    (v_aula_id, 1, $p$Num mundo que nos faz sentir insignificantes, você crê de verdade que, sendo único, Deus quer usar a sua vida para algo que ninguém mais poderia fazer?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O que tem impedido você de fazer "o algo que pode fazer", mesmo sem poder fazer tudo?$p$, 'reflexao', null),
